                    (#[trigger] lock2x.rows[h2x as nat].token.value()[j] matches Some((k, _)) ==> k != key),
            decreases WIDTH - i,
        {
            let entry = self.matrix[h2x].borrow(
                Tracked(&lock2x.rows.tracked_borrow(h2x as nat).pt))[i];
            if entry.is_some() && entry.unwrap().0 == key {
