                try_open_atomic_update!(au, mut mpt => {
                    proof {
                        r = lock1x.rows.tracked_remove(h1x as nat);
                        let tracked other_r = lock2x.rows.tracked_borrow(h2x as nat);
                        let tracked (Tracked(mpt0), Tracked(tok0)) =
