    lemma_imap_empty,
    lemma_imap_insert_domain,
    lemma_imap_insert_same,
    lemma_imap_insert_different,
    lemma_imap_remove_domain,
    lemma_imap_remove_different,
    lemma_imap_ext_equal,
    lemma_imap_ext_equal_deep,
}

